resolved as (
    select
        HUB_PARTY_HK,
        CONTACT_POINT_TYPE,
        CONTACT_PRIORITY_ORDER,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then EMAIL_ADDRESS end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then EMAIL_ADDRESS end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then EMAIL_ADDRESS end)) as EMAIL_ADDRESS,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then LANDLINE_NUMBER end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then LANDLINE_NUMBER end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then LANDLINE_NUMBER end)) as LANDLINE_NUMBER,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then FAX_NUMBER end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then FAX_NUMBER end)) as FAX_NUMBER,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then MOBILE_NUMBER end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then MOBILE_NUMBER end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then MOBILE_NUMBER end)) as MOBILE_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ALTERNATE_EMAIL_ADDRESS end) as ALTERNATE_EMAIL_ADDRESS,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ALTERNATE_MOBILE_NUMBER end) as ALTERNATE_MOBILE_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then STD_CODE end) as STD_CODE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PARTY_HK, CONTACT_POINT_TYPE, CONTACT_PRIORITY_ORDER
),

hashed as (
    select
        *,
        case when CONTACT_POINT_TYPE is not null or CONTACT_PRIORITY_ORDER is not null or EMAIL_ADDRESS is not null or LANDLINE_NUMBER is not null or FAX_NUMBER is not null or MOBILE_NUMBER is not null or ALTERNATE_EMAIL_ADDRESS is not null or ALTERNATE_MOBILE_NUMBER is not null or STD_CODE is not null
                     then md5(upper(coalesce(cast(CONTACT_POINT_TYPE as varchar), '') || '|' || coalesce(cast(CONTACT_PRIORITY_ORDER as varchar), '') || '|' || coalesce(cast(EMAIL_ADDRESS as varchar), '') || '|' || coalesce(cast(LANDLINE_NUMBER as varchar), '') || '|' || coalesce(cast(FAX_NUMBER as varchar), '') || '|' || coalesce(cast(MOBILE_NUMBER as varchar), '') || '|' || coalesce(cast(ALTERNATE_EMAIL_ADDRESS as varchar), '') || '|' || coalesce(cast(ALTERNATE_MOBILE_NUMBER as varchar), '') || '|' || coalesce(cast(STD_CODE as varchar), '')))
                end as SAT_COMMON_CONTACT_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PARTY_HK is not null
  and SAT_COMMON_CONTACT_HASHDIFF is not null
